result = [3, 3, 3, 3, 3, 0, 3, 3, 3, 2, 3, 3, 3, 2, 1, 2, 2, 2, 1, 1, 1, 0, 0, 0]

# Show which numbers are in each subset
subsets = {0: [], 1: [], 2: [], 3: []}
for i, s in enumerate(result):
    subsets[s].append(i + 1)

for s in range(4):
    print(f"Subset {s}: {subsets[s]} -> sum = {sum(subsets[s])}")
